    c1 = max(c for r, c in marked)

    # Identify a row-reflection axis from rows that are not masked.
    best_k, best_score = h - 1, -1
    for k in range(2 * h):
        score = 0
        for r in range(h):
            rr = k - r
            if not (0 <= rr < h) or rr == r:
                continue
            a = [grid[r][c] for c in range(w) if grid[r][c] != 8 and grid[rr][c] != 8]
            b = [grid[rr][c] for c in range(w) if grid[r][c] != 8 and grid[rr][c] != 8]
            if a and a == b:
                score += len(a)
        if score > best_score:
            best_k, best_score = k, score

    out = []
    for r in range(r0, r1 + 1):
        row = []
        for c in range(c0, c1 + 1):
            value = grid[r][c]
            if value == 8:
                rr = best_k - r
                if 0 <= rr < h and grid[rr][c] != 8:
                    value = grid[rr][c]
                else:
                    # For an entirely masked reflected pair, borrow the
                    # prefix of the row with the closest visible suffix.
                    donors = []
                    for sr in range(h):
                        if sr == r or grid[sr][c] == 8:
                            continue
                        distance = sum(
                            grid[r][x] != grid[sr][x]
                            for x in range(w)
                            if grid[r][x] != 8 and grid[sr][x] != 8
                        )
                        donors.append((distance, sr))
                    if donors:
                        value = grid[min(donors)[1]][c]
            row.append(value)
        out.append(row)
